pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testRegression_property() public {
        address logAddr = address(new LogFile());
        c.SetLogFile(logAddr);
        c.Initialized();

        vm.deal(address(this), 1 ether);
        bool ok;
        try c.Deposit{value: 1 wei}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
